-- Query session over one run's parquets/ directory.
-- Expects: SET VARIABLE parquets = '<run>/parquets'; and lib.sql loaded.
-- Per-namespace views ("Forge.Loop.ForgedBlock", ...) are generated by bench-parquet
-- from the namespaces present in the run, after this file.

-- Raw layer: stdout of every process (the default), stderr separately.
CREATE OR REPLACE VIEW raw        AS SELECT * FROM read_parquet(getvariable('parquets') || '/*/stdout.parquet');
CREATE OR REPLACE VIEW raw_stderr AS SELECT * FROM read_parquet(getvariable('parquets') || '/*/stderr.parquet');

-- Metadata.
CREATE OR REPLACE VIEW run_meta   AS SELECT * FROM read_parquet(getvariable('parquets') || '/run.parquet');
CREATE OR REPLACE VIEW files      AS SELECT * FROM read_parquet(getvariable('parquets') || '/files.parquet');

-- Severity, ordered as in trace-dispatcher's SeverityS. Stored as text; this type
-- only serves comparisons: sev_level(sev) >= 'Warning'. Strict: an unknown value
-- is an error.
CREATE TYPE severity AS ENUM ('Debug', 'Info', 'Notice', 'Warning', 'Error', 'Critical', 'Alert', 'Emergency');
CREATE OR REPLACE MACRO sev_level(s) AS CAST(s AS severity);

-- Fields that are stable in practice. Strict casts: a type change is an error,
-- never a NULL.
CREATE OR REPLACE MACRO slot_no(d)       AS CAST(d->>'$.slot'               AS UBIGINT);
CREATE OR REPLACE MACRO mempool_txs(d)   AS CAST(d->>'$.mempoolSize.numTxs' AS UBIGINT);
CREATE OR REPLACE MACRO mempool_bytes(d) AS CAST(d->>'$.mempoolSize.bytes'  AS UBIGINT);
-- Resources record fields:
CREATE OR REPLACE MACRO res_cpu(d)       AS CAST(d->>'$.CentiCpu' AS UBIGINT);  -- centiseconds, cumulative
CREATE OR REPLACE MACRO res_gc(d)        AS CAST(d->>'$.CentiGC'  AS UBIGINT);  -- centiseconds, cumulative
CREATE OR REPLACE MACRO res_mut(d)       AS CAST(d->>'$.CentiMut' AS UBIGINT);  -- centiseconds, cumulative
CREATE OR REPLACE MACRO res_rss(d)       AS CAST(d->>'$.RSS'      AS UBIGINT);  -- bytes
CREATE OR REPLACE MACRO res_heap(d)      AS CAST(d->>'$.Heap'     AS UBIGINT);  -- bytes
CREATE OR REPLACE MACRO res_live(d)      AS CAST(d->>'$.Live'     AS UBIGINT);  -- bytes
CREATE OR REPLACE MACRO res_alloc(d)     AS CAST(d->>'$.Alloc'    AS UBIGINT);  -- bytes, cumulative
CREATE OR REPLACE MACRO res_gcs_major(d) AS CAST(d->>'$.GcsMajor' AS UBIGINT);  -- count, cumulative
CREATE OR REPLACE MACRO res_gcs_minor(d) AS CAST(d->>'$.GcsMinor' AS UBIGINT);  -- count, cumulative
CREATE OR REPLACE MACRO res_threads(d)   AS CAST(d->>'$.Threads'  AS UBIGINT);
